import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const createRes = await member.post("/api/vendors", {
    data: { name: uniqueName("Audit Vendor"), category: "services", contact_email: "ops@auditvendor.example" },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = (await createRes.json()) as { id: string };

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = (await uploadRes.json()) as { id: string };

  // Extraction runs in the background; wait until it has finished.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        expect(res.status(), await res.text()).toBe(200);
        return ((await res.json()) as { status: string }).status;
      },
      { timeout: 15_000 },
    )
    .toBe("extracted");

  // Act
  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const { items } = (await auditRes.json()) as {
    items: { action: string; at: string; actor: { id: string; name: string; email: string } }[];
  };
  expect(items.map((e) => e.action)).toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

  for (const event of items) {
    expect(event.actor.id, "actor id").toBeTruthy();
    expect(event.actor.email, "actor email").toBeTruthy();
    expect(Number.isNaN(Date.parse(event.at)), `timestamp ${event.at}`).toBe(false);
  }

  const times = items.map((e) => Date.parse(e.at));
  expect(times).toEqual([...times].sort((a, b) => a - b));
});
